// No inputs; just exercise the API and sanity-check result domain
uint32_t v = amqp_version_number();
// Property: version is a packed 32-bit number; nothing else to enforce here
(void)v;
// Validation: stub calls function and accepts any value; no persistent objects involved.

// No inputs; returns a static, process-lifetime string
const char *ver = amqp_version();
// Do not free/modify; just touch it so optimizers don't elide the call
if (!ver) { FUZZ_BAIL(); }
volatile char c = ver[0];
(void)c;
// Validation: ensures non-null pointer and avoids freeing static storage.

// pagesize must be reasonable; keep <= 2048 for perf and >= 16 for alignment/leeway
size_t pagesize = (size_t)(*FUZZ_PARAM(unsigned int) % 2033u) + 16u;
init_amqp_pool(pool, pagesize);
// Track initialization state and config
FUZZ_SET_ATTR_INT(pool, "initialized", 1);
FUZZ_SET_ATTR_INT(pool, "pagesize", (int)pagesize);
FUZZ_SET_ATTR_INT(pool, "generation", FUZZ_GET_ATTR_INT(pool, "generation") + 1);
// Output: pool remains valid and managed by API
// Validation: marks pool as initialized with chosen pagesize.

// Must be initialized before recycle
if (!FUZZ_GET_ATTR_INT(pool, "initialized")) { FUZZ_BAIL(); }
recycle_amqp_pool(pool);
// Invalidate previous allocations and bump generation to reflect invalidation
FUZZ_SET_ATTR_INT(pool, "generation", FUZZ_GET_ATTR_INT(pool, "generation") + 1);
// Validation: ensures only initialized pools are recycled; pool is returned for continued use.

// Must be initialized before empty
if (!FUZZ_GET_ATTR_INT(pool, "initialized")) { FUZZ_BAIL(); }
empty_amqp_pool(pool);
// Note: empties all memory; allocations become invalid; mark state
FUZZ_SET_ATTR_INT(pool, "emptied", FUZZ_GET_ATTR_INT(pool, "emptied") + 1);
FUZZ_SET_ATTR_INT(pool, "generation", FUZZ_GET_ATTR_INT(pool, "generation") + 1);
// Validation: preserves pool handle while recording that all allocations are invalidated.

// Require initialized pool
if (!FUZZ_GET_ATTR_INT(pool, "initialized")) { FUZZ_BAIL(); }
// Allocate a small block (1..1024). amount==0 would just return NULL; we exercise non-zero path
size_t amount = ((size_t)(*FUZZ_PARAM(unsigned int) % 1024u)) + 1u;
void *p = amqp_pool_alloc(pool, amount);
// p may be NULL if OOM; that's acceptable per API
(void)p;
// Validation: respects ownership (pool-owned) and returns pool for continued use.

// Require initialized pool
if (!FUZZ_GET_ATTR_INT(pool, "initialized")) { FUZZ_BAIL(); }
// Randomly exercise amount including zero: 0..1024
size_t amount = (size_t)(*FUZZ_PARAM(unsigned int) % 1025u);
amqp_bytes_t out = {0};
amqp_pool_alloc_bytes(pool, amount, &out);
// out.bytes may be NULL if amount==0 or OOM; do not free (pool-owned)
// We do not persist out beyond this stub to avoid dangling across pool recycle/empty
(void)out;
// Validation: enforces initialization and uses API contract for zero/non-zero amounts; pool remains output.

// Generate a fuzz string and pass its stable c_str() to the wrapper
std::string s = FUZZ_PARAM_STR();
const char *cstr = s.c_str();
amqp_bytes_t wrapped = amqp_cstring_bytes(cstr);
// The wrapper points into s; ensure s stays alive until after the call
(void)wrapped;
// Validation: ensures valid null-terminated input and non-owning lifetime semantics.

// Build a source amqp_bytes_t from fuzz data (non-owning)
std::string src_data = FUZZ_PARAM_STR();
amqp_bytes_t src;
src.len = src_data.size();
src.bytes = (void *)src_data.data();
// Duplicate into a newly allocated buffer
amqp_bytes_t dup = amqp_bytes_malloc_dup(src);
if (!dup.bytes && dup.len != 0) { FUZZ_BAIL(); }
if (!dup.bytes && dup.len == 0 && src.len != 0) { FUZZ_BAIL(); }
// Persist the bytes descriptor as an object we own; it must be freed with amqp_bytes_free()
amqp_bytes_t *bytes_obj = (amqp_bytes_t *)amqp_pool_alloc((amqp_pool_t *)nullptr, sizeof(amqp_bytes_t));
if (!bytes_obj) {
  // Fallback to heap if no pool; keep allocation small
  bytes_obj = (amqp_bytes_t *)malloc(sizeof(amqp_bytes_t));
}
if (!bytes_obj) { FUZZ_BAIL(); }
*bytes_obj = dup;
