            else:
                # 4-byte
                cp = rng.randint(0x10000, 0x10FFFF)
                b1 = 0xF0 | (cp >> 18)
                b2 = 0x80 | ((cp >> 12) & 0x3F)
                b3 = 0x80 | ((cp >> 6) & 0x3F)
                b4 = 0x80 | (cp & 0x3F)
                out.extend((b1, b2, b3, b4))
        return bytes(out[:n])
    if pattern_id == 8:
        # random binary
        return rng.randbytes(n)
    if pattern_id == 9:
        # mixed segments of previous patterns
        segs = []
        remaining = n
        while remaining > 0:
            seg_len = min(remaining, max(1, int(rng.paretovariate(2) * 8) % (remaining + 1)))
            seg_pat = rng.randint(0, 6)
            segs.append(_pattern_bytes(seg_pat, seg_len, rng))
            remaining -= seg_len
        return b"".join(segs)
    return rng.randbytes(n)

def _embed_special_subsequences(buf, rng):
    # Insert some interesting subsequences like C-strings, repeated keys, AMQP-like tokens
    specials = []
    # Null-terminated strings
    if rng.random() < 0.6:
        s = b"guest\x00guest\x00"
        specials.append(s)
    if rng.random() < 0.5:
        specials.append(b"amqp\x00")
    if rng.random() < 0.5:
        specials.append(b"/\x00")
    if rng.random() < 0.4:
        specials.append(b"exchange\x00default\x00")
    if not specials:
        return buf
    out = bytearray(buf)
    for s in specials:
        if len(out) + len(s) > _MAX_SIZE:
            break
        pos = rng.randint(0, max(0, len(out)))
        out[pos:pos] = s
    if len(out) > _MAX_SIZE:
        del out[_MAX_SIZE:]
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose an overall strategy: size and content pattern
    length = _interesting_lengths(rng)

    # Bias: sometimes generate empty, tiny, or boundary buffers exactly
    if rng.random() < 0.15:
        length = _weighted_choice(rng, [(3, 0), (3, 1), (3, 8), (2, 16), (2, 32), (2, 64), (1, 128), (1, 256)])

    pattern = _weighted_choice(rng, [
        (2, 0),  # zeros
        (2, 1),  # 0xFF
        (3, 2),  # ascending
        (2, 3),  # descending
        (1, 4),  # word sequence
        (1, 5),  # dword sequence
        (3, 6),  # printable ascii
        (3, 7),  # utf-8 like
        (3, 8),  # random binary
        (2, 9),  # mixed segments
    ])

    data = _pattern_bytes(pattern, length, rng)

    # Occasionally embed special subsequences that look like typical AMQP strings
    if rng.random() < 0.5 and len(data) < _MAX_SIZE:
        data = _embed_special_subsequences(data, rng)

    # Ensure size constraint
    if len(data) > _MAX_SIZE:
        data = data[:_MAX_SIZE]
    return data

import random
import struct
import string
from typing import List, Tuple

# Generate a valid AMQP 0-9-1 Field Table in wire format.
# Reference layout (per spec and rabbitmq-c expectations):
# table := U32 length L followed by L bytes of: repeated entries
# entry := shortstr key (1-byte len N, then N bytes), 1-byte type tag, then value
# value depends on tag. We will stick to commonly supported simple types and nested ones:
#  - 't' boolean: 1 byte 0/1
#  - 'b' int8: 1 byte signed
#  - 'B' uint8: 1 byte
#  - 's' int16: 2 bytes signed big-endian
#  - 'u' uint16: 2 bytes big-endian
#  - 'I' int32: 4 bytes signed big-endian
#  - 'i' uint32: 4 bytes big-endian
#  - 'l' int64: 8 bytes big-endian
#  - 'L' uint64: 8 bytes big-endian
#  - 'f' float32: 4 bytes IEEE big-endian
#  - 'd' float64: 8 bytes IEEE big-endian
#  - 'D' decimal: 1 byte decimals, 4 bytes uint32 value big-endian
#  - 'S' long string: 4-byte length, then bytes (UTF-8)
#  - 'x' byte array: 4-byte length, then bytes
#  - 'T' timestamp: uint64 big-endian
#  - 'F' field table (nested): table
#  - 'A' field array: 4-byte length L; then sequence of field values (each starts with type then payload) filling exactly L bytes
#  - 'V' void: no payload
# The fuzz harness may choose an arbitrary offset into the buffer, so we optionally prepend/append padding.

MAX_TOTAL = 4096

def be_u32(n: int) -> bytes:
    return struct.pack(">I", n & 0xFFFFFFFF)

def be_u16(n: int) -> bytes:
    return struct.pack(">H", n & 0xFFFF)

def be_i16(n: int) -> bytes:
    return struct.pack(">h", int(n))

def be_i32(n: int) -> bytes:
    return struct.pack(">i", int(n))

def be_u64(n: int) -> bytes:
    return struct.pack(">Q", n & 0xFFFFFFFFFFFFFFFF)

def be_i64(n: int) -> bytes:
    return struct.pack(">q", int(n))

def be_f32(x: float) -> bytes:
    return struct.pack(">f", float(x))

def be_f64(x: float) -> bytes:
    return struct.pack(">d", float(x))

def shortstr(s: str) -> bytes:
    b = s.encode("utf-8", errors="strict")
    if len(b) > 255:
        b = b[:255]
    return struct.pack("B", len(b)) + b

def longstr(b: bytes) -> bytes:
    return be_u32(len(b)) + b

def rand_key(r: random.Random) -> str:
    # AMQP requires key to be a shortstr (<=255), usually ASCII and <=128 bytes in this lib's struct description
    length = r.randint(1, min(20, 128))
    alphabet = string.ascii_letters + string.digits + "_-:."
    return "".join(r.choice(alphabet) for _ in range(length))

def gen_boolean(r: random.Random) -> bytes:
    return b"t" + (b"\x01" if r.choice([True, False]) else b"\x00")

def gen_int_variants(r: random.Random) -> bytes:
    choice = r.choice(['b','B','s','u','I','i','l','L'])
    if choice == 'b':
        return b"b" + struct.pack("b", r.randint(-128, 127))
    if choice == 'B':
        return b"B" + struct.pack("B", r.randint(0, 255))
    if choice == 's':
        return b"s" + be_i16(r.randint(-32768, 32767))
    if choice == 'u':
        return b"u" + be_u16(r.randint(0, 65535))
    if choice == 'I':
        return b"I" + be_i32(r.randint(-2**31, 2**31-1))
    if choice == 'i':
        return b"i" + be_u32(r.getrandbits(32))
    if choice == 'l':
        return b"l" + be_i64(r.randint(-2**63+1, 2**63-1))
    if choice == 'L':
        return b"L" + be_u64(r.getrandbits(64))
    return gen_boolean(r)

def gen_float(r: random.Random) -> bytes:
    if r.random() < 0.5:
        return b"f" + be_f32(r.uniform(-1e6, 1e6))
    else:
        return b"d" + be_f64(r.uniform(-1e12, 1e12))

def gen_decimal(r: random.Random) -> bytes:
    decimals = r.randint(0, 9)
    value = r.randint(0, 2**32-1)
    return b"D" + struct.pack("B", decimals) + be_u32(value)

def gen_longstr(r: random.Random) -> bytes:
    # UTF-8 string for 'S'
    size = r.randint(0, 128)
    alphabet = string.ascii_letters + string.digits + " _-./:@"
    s = "".join(r.choice(alphabet) for _ in range(size))
    return b"S" + longstr(s.encode("utf-8"))

def gen_bytes(r: random.Random) -> bytes:
    size = r.randint(0, 128)
    data = r.randbytes(size) if hasattr(r, 'randbytes') else bytes([r.randrange(256) for _ in range(size)])
    return b"x" + longstr(data)

def gen_timestamp(r: random.Random) -> bytes:
    # Reasonable epoch range
    ts = r.randint(0, 2**40)  # within reasonable size
    return b"T" + be_u64(ts)

def gen_array(r: random.Random, depth: int) -> bytes:
    # Field array: length then concatenated typed values, same-type recommended but spec allows mixed
    # We generate a few homogeneous or heterogeneous entries
    num = r.randint(0, 6)
    elems: List[bytes] = []
    for _ in range(num):
        elems.append(gen_field_value(r, depth+1, array_context=True))
    payload = b"".join(elems)
    return b"A" + be_u32(len(payload)) + payload

def gen_table(r: random.Random, depth: int) -> bytes:
    # Nested table: we generate a small inner table payload (without outer length; we'll wrap with a U32 length)
    entries = r.randint(0, 6)
    inner = b""
    used_keys = set()
    for _ in range(entries):
        key = rand_key(r)
        if key in used_keys:
            # ensure unique keys
            continue
        used_keys.add(key)
        kv_payload = gen_field_value(r, depth+1)
        inner += shortstr(key) + kv_payload
    return b"F" + be_u32(len(inner)) + inner

def gen_void(r: random.Random) -> bytes:
    return b"V"

def gen_field_value(r: random.Random, depth: int, array_context: bool=False) -> bytes:
    # Limit nesting depth to keep buffers small and valid
    max_depth = 2
    simple_generators = [gen_boolean, gen_int_variants, gen_float, gen_decimal, gen_longstr, gen_bytes, gen_timestamp, gen_void]
    complex_generators = []
    if depth < max_depth:
        complex_generators = [lambda rr: gen_table(rr, depth), lambda rr: gen_array(rr, depth)]
    gens = simple_generators + complex_generators
    # Bias arrays to sometimes be homogeneous when inside an array
    if array_context and depth < max_depth and r.random() < 0.5:
        # choose one simple type and repeat a few times
        g = r.choice(simple_generators)
        count = r.randint(1, 5)
        elems = [g(r) for _ in range(count)]
        payload = b"".join(elems)
        return b"A" + be_u32(len(payload)) + payload
    g = r.choice(gens)
    return g(r)

def build_table_bytes(r: random.Random) -> bytes:
    entries = r.randint(1, 8)
    used_keys = set()
    body = b""
    for _ in range(entries):
        key = rand_key(r)
        if key in used_keys:
            continue
        used_keys.add(key)
        value = gen_field_value(r, 0)
        body += shortstr(key) + value
    return be_u32(len(body)) + body

def maybe_add_padding(r: random.Random, core: bytes) -> bytes:
    # Fuzzer chooses random offset; adding random prefix/suffix ensures there are bytes before/after
    prefix_len = r.randint(0, 16)
    suffix_len = r.randint(0, 16)
    prefix = b"" if prefix_len == 0 else (r.randbytes(prefix_len) if hasattr(r,'randbytes') else bytes([r.randrange(256) for _ in range(prefix_len)]))
    suffix = b"" if suffix_len == 0 else (r.randbytes(suffix_len) if hasattr(r,'randbytes') else bytes([r.randrange(256) for _ in range(suffix_len)]))
    return prefix + core + suffix

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Randomly choose to generate either a stand-alone table, or a buffer containing multiple back-to-back tables
    # since the stub caps to 1024 and may start at any offset.
    parts: List[bytes] = []
    mode = r.choice(["single", "multi", "nested"])
    if mode == "single":
        core = build_table_bytes(r)
        buf = maybe_add_padding(r, core)
    elif mode == "multi":
        n = r.randint(2, 4)
        for _ in range(n):
            parts.append(build_table_bytes(r))
        core = b"".join(parts)
        buf = maybe_add_padding(r, core)
    else:  # nested top-level single table including nested tables/arrays
        core = build_table_bytes(r)
        buf = maybe_add_padding(r, core)

    # Ensure size limits for harness performance (< 1024 preferred; hard cap 4096)
    if len(buf) > 1024:
        buf = buf[:1024]
    if len(buf) == 0:
        # Always produce something valid; at least an empty table
        empty = be_u32(0)
        buf = maybe_add_padding(r, empty)
    return buf
